<script setup lang="ts">
import SortableTable from '../../shared/ui/SortableTable.vue'
import type { ImportRow } from '../../api/imports'
import { importedStates } from '../../api/imports'
defineProps<{row:ImportRow}>()
const labels:Record<string,string>={registration_number:'Текущий номер',historical_number:'Исторический номер',sequence:'Порядковый номер',department_code:'Код отдела',category_code:'Категория дела',year:'Год',state:'Состояние',specialty_code:'Специальность',received_on:'Поступление',source_end_on:'Дата в колонке P',completed_on:'Окончание экспертизы',issued_on:'Фактическая передача по отметке',result_kind:'Вид результата',complexity_level:'Сложность',questions:'Вопросы',categorical:'Категорические выводы',probable:'Вероятные выводы',unresolved:'Нерешённые вопросы',unresolved_note:'Пометка количества',unresolved_reason_raw:'Исходная причина',amount:'Сумма',legacy_duration_days:'Исходная длительность',authority_type:'Тип органа',authority_name:'Орган',official:'Должностное лицо',contact:'Контакт',basis_text:'Основание из таблицы',case_description:'Сведения дела',inventory:'Материалы',executor_raw:'Эксперт в источнике',notes:'Комментарий',delivery:'Отметки'}
const kinds:Record<string,string>={expert_conclusion:'Заключение эксперта',research_act:'Акт исследования',sndz:'СНДЗ'}
function display(key:string,value:string|number|null){if(value===null||value==='')return 'Не указано';return key==='state'?importedStates[String(value)]||value:key==='result_kind'?kinds[String(value)]||value:value}
</script>
<template><section data-import-row-details class="card stack-card"><h2>Строка {{row.source_row}}</h2><p class="muted">Это сведения источника, ещё не рабочая экспертиза. Фамилии не создают сотрудников и назначения автоматически.</p><h3>Что проверить</h3><ul v-if="row.diagnostics.length"><li v-for="(item,index) in row.diagnostics" :key="index"><span class="badge" :class="item.severity==='error'?'badge-amber':''">{{item.columns.join(', ')||'Строка'}}</span> {{item.message}}</li></ul><p v-else>Ошибок разбора не найдено. Это не подтверждает полноту для применения или отчёта.</p><h3>Разобранные сведения</h3><dl class="work-facts"><div v-for="(value,key) in row.facts" :key="key"><dt>{{labels[key]||key}}</dt><dd class="source-text">{{display(key,value)}}</dd></div></dl><h3>Исходные ячейки</h3><div class="table-scroll"><SortableTable :rows="[...Object.entries(row.raw).map(([column,value])=>({column,value,formula:row.formulas[column]||'—'})),...Object.entries(row.extra).map(([column,value])=>({column:column+' · вне схемы',value,formula:''}))]" :columns="[{key:'column',label:'Колонка'},{key:'value',label:'Исходное значение',value:r=>String(r.value??'')},{key:'formula',label:'Формула'}]" v-slot="{rows:tableRows}"><tr v-for="cell in tableRows" :key="cell.column"><td>{{cell.column}}</td><td class="source-text">{{cell.value===null?'Пустая ячейка':cell.value}}</td><td class="source-text">{{cell.formula}}</td></tr></SortableTable></div></section></template>
<style scoped>.source-text{white-space:pre-wrap;overflow-wrap:anywhere;max-width:64ch}</style>
